			defer wg.Done()
			<-start
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(http.MethodPost, "/v1/idempotency/records", bytes.NewBufferString(bodies[i]))
			request.Header.Set("Content-Type", "application/json")
			router.ServeHTTP(recorder, request)
			switch recorder.Code {
			case http.StatusOK:
				if recorder.Header().Get("Idempotency-Outcome") != "created" {
					t.Fatalf("winner outcome = %q", recorder.Header().Get("Idempotency-Outcome"))
				}
			case http.StatusConflict:
				if got := recorder.Header().Get("Idempotency-Outcome"); got != "" {
